export function imprimerRecu(r: any) {
  const money = (v: number) => (v ?? 0).toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' DA';
  const w = window.open('', '_blank', 'width=700,height=800');
  if (!w) { alert('Autorisez les fenêtres pop-up pour imprimer.'); return; }
  w.document.write(`<html><head><title>${r.numeroRecu}</title><style>
    body{font-family:Arial;padding:30px;max-width:620px;margin:auto} h1{text-align:center;margin-bottom:4px}
    .n{text-align:center;color:#555;margin-bottom:24px} table{width:100%;border-collapse:collapse}
    td{padding:8px;border-bottom:1px solid #ddd} td:first-child{color:#555;width:40%}
    .m{font-size:20px;font-weight:bold} .sig{display:flex;justify-content:space-between;margin-top:60px}</style></head><body>
    <h1>REÇU DE PAIEMENT</h1><div class="n">N° ${r.numeroRecu}</div>
    <table>
      <tr><td>Date</td><td>${new Date(r.date).toLocaleString('fr-FR')}</td></tr>
      <tr><td>Client</td><td>${r.client}</td></tr>
      <tr><td>Chantier / Lot</td><td>${r.chantier} — ${r.lot}</td></tr>
      <tr><td>Mode de paiement</td><td>${r.mode === 'Especes' ? 'Espèces' : 'Bancaire'}${r.refBancaire ? ' (' + r.refBancaire + ')' : ''}</td></tr>
      <tr><td>Montant encaissé</td><td class="m">${money(r.montant)}</td></tr>
      <tr><td>Prix total</td><td>${money(r.prixTotal)}</td></tr>
      <tr><td>Total payé à ce jour</td><td>${money(r.totalPaye)}</td></tr>
      <tr><td>Reste à payer</td><td>${money(r.reste)}</td></tr>
      <tr><td>Encaissé par</td><td>${r.agent ?? ''}</td></tr>
    </table>
    <div class="sig"><span>Signature du client</span><span>Cachet et signature</span></div>
    <script>window.onload=()=>window.print()</script></body></html>`);
  w.document.close();
}
